INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('5wl6c3mwfvqyh18naypwv4enpt55wl6c', '2026-Q3', 'Set/2026 (T3)', '2026-09-18T15:43'::timestamptz, 'Joalicio de Almeida Honório Junior', 'joalicio de almeida honorio junior', 'PHARUS', 'João Aliceda', 4.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Entrei a pouco tempo. Mas, ainda não recebi o planejamento prometido, mesmo após enviar todas informações solicitadas. Outro ponto são comprovações fiéis do que já foi feito e o que estão fazendo, documentados para dar mais credibilidade ao trabalho, uma vez que a maioria das pessoas que entraram agora assim como eu, vimos apenas em rede social, que diga de passagem e uma terra sem lei. Outra coisa que me chamou muita atenção NEGATIVA são os processos feitos por pessoas que por algum motivo não conseguiu cancelar o contrato após desistir. Sem avaliar o mérito de quem está certo ou errado, mas pega mal e pode atrapalhar negócios futuros.', 'Mais transparecia e comprovação via documentos que comprovem a idoneidade da empresa e de todos envolvidos', NULL, 'Transparência e entrega do planejamento', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '5wl6c3mwfvqyh18naypwv4enpt55wl6c', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, progra