INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('1v23als9vbflj911xmin1v23a0omuu2h', '2026-Q3', 'Set/2026 (T3)', '2026-09-18T17:18'::timestamptz, 'Nadja Helena Martins Saraiva', 'nadja helena martins saraiva', 'PHARUS', 'Nelson Marques', 10.0, 'Promotor', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'O programa tem me ajudado a ter mais clareza na minha relação com o dinheiro. Tem me feito parar, refletir sobre meus comportamentos financeiros e, principalmente, repensar meu posicionamento em relação aos meus investimentos.', NULL, 'O que mais me agradou foi o contato semanal e a possibilidade de ter alguém com quem conversar, trocar e refletir sobre minhas decisões. Faz muita diferença saber que estou falando com uma pessoa que entende a minha realidade e fala a mesma linguagem que eu. Isso torna o processo mais próximo, prático e aplicável à minha vida.', 'Resultado. Continuar percebendo, de forma concreta, que o programa está gerando evolução nas minhas decisões, no meu comportamento financeiro e, principalmente, nos resultados do meu patrimônio.', 'Nesse momento não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '1v23als9vbflj911xmin1v23a0omuu2h', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.progr