INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('j2ukwva77zkd7cpwj2ukwvgbque1c03f', '2026-Q3', 'Set/2026 (T3)', '2026-09-19T20:28'::timestamptz, 'Guilherme Maximiliano Lima', 'guilherme maximiliano lima', 'PHARUS', 'João Aliceda', 5.0, 'Detrator', 7.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Entendi o método, mas ainda não implementei o suficiente', 'Ainda estou conhecendo o programa e confesso que ainda estou desconfiado se é um bom negócio. As primeiras opções apresentadas de Leilão e compra de imóveis na planta não eram atrativas e não garantiriam o payback proposto (no segundo caso gerando até prejuízo). Não está claro sobre os ganhos da quarta via em cada oportunidade apresentada. Falta transparência. Exemplo é o Arcádia com $8k depositado no Brasil e não fazendo parte do LLC (que abrange os outros 32k das quotas). Para mim isso é puro lucro da quarta via, mas não existe essa transparência de que é assim que funciona. Outro ponto: os contratos trazem todo o risco  das operações para o cliente, que não tem liberdade para solicitar nenhuma modificação.', '1. Maior transparência quanto aos ganhos da Quarta Via em cada negocio proposto. 2. Flexibilidade em ajustes contratuais. 3. Compartilhamento de riscos das operações, já que na maioria das vezes, a Quarta avia tem plenos poderes.', NULL, '“Eu tinha expectativa de que eu teria aprendizado de como implantar por mim mesmo, mas a assessoria se limita a prover apenas produtos de parceiros ou da própria empresa. Confesso que esse ponto me frustrou. Por isso ressalto que, com este modelo, ainda precisa melhorar enormemente a transparência das operações propostas. Minha impressão é que estão me oferecendo opções que favoreçam a quarta via e não a mim, já que no mercado encontro oportunidades muito mais atraentes.', 'Não', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'j2ukwva77zkd7cpwj2ukwvgbque1c03f', 'cadastro 2026-T3 (respondente) (0 dias)', 'cadastro 2026-T3') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('r1lmttrkjwvxuvr1lmt3hesnaekaokg5', '2026-Q3', 'Set/2026 (T3)', '2026-09-20T15:55'::timestamptz, 'Ana Paula Pereira Pinto', 'ana paula pereira pinto', 'PHARUS', 'João Aliceda', 0.0, 'Detrator', 5.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Os dados financeiros estão errados desde que foi preenchido em julho/2026 e até hoje não ajustaram, apesar de já termos pedido pra corrigir diversas vezes.', 'Ter uma assessoria que nos oriente a fazer investimentos que estejam alinhados aos nossos projetos futuros.', NULL, 'Ter resultados acima da média do mercado.', 'Ele começou bem, mas apesar dos nossos pedidos não resolveu o problema da plataforma e até agora não nos ofereceu nada que estivesse alinhado ao nosso momento para investimento.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'r1lmttrkjwvxuvr1lmt3hesnaekaokg5', 'cadastro 2026-T3 (respondente) (0 dias)', 'cadastro 2026-T3') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano