INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('f82jsgf4cwe2ue2styf82jsghx7e4li9', '2026-Q3', 'Set/2026 (T3)', '2026-09-20T23:45'::timestamptz, 'Robson Silva', 'robson silva', 'PHARUS', 'Nelson Marques', 7.0, 'Neutro', 9.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Achei q era uma coisa, entrei para investir fora e agora vi q é um plano de acompanhamento e isso eu não estava interessado de fazer', 'Ser transparente desde o início', NULL, 'Ter clareza nos resultados não adianta eu pagar para ter um acompanhamento e não ter ganhos q façam isso valer a pena', 'A venda inicial era fazer investimentos nos EUA só q vi q não é isso q o programa faz depois de já ter entrado, sinceramente arrependido não era isso q eu queria', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'f82jsgf4cwe2ue2styf82jsghx7e4li9', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.pl