INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('8ongd9nc527xhha8ongdx4gmdw1kbztg', '2026-Q3', 'Set/2026 (T3)', '2026-09-21T16:40'::timestamptz, 'Thiago Techio de Castro', 'thiago techio de castro', 'PHARUS', 'Felipe Aleixo', 5.0, 'Detrator', 10.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Tenho clareza e estou executando com consistência', 'A ideia é boa, o atendimento é muito bom, o nível de conhecimento é muito, acima do esperado, mas a implementação não é tão simples, muito da estratégia está pautada na confiança que quem está com a procuração irá fazer um trabalho bom. Tem contratos e tudo mais, mas no final das contas de der merda os contrária possuem cláusulas que eximem os administradores/gestores. Para quem não tem noção de mercado financeiro e de financas pessoais agrega muito o bate papo com os acessores, mas para quem já tem um nível melhor o que agrega são os investimentos conjuntos.', 'A experiência está sendo boa, a recomendação é que ainda não me sinto seguro em fazer tendo em vista que não implementei nenhuma estrutura que tenha me dado retorno por enquanto.', NULL, 'Resultados objetivos', 'No momento não.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', '8ongd9nc527xhha8ongdx4gmdw1kbztg', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
