INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('oy10d4gmjgrhyh3aouoy10icnzukgij6', '2026-Q3', 'Set/2026 (T3)', '2026-09-21T17:52'::timestamptz, 'Pedro Emílio de Souza Braga', 'pedro emilio de souza braga', 'PHARUS', 'Samuel Araújo', 3.0, 'Detrator', 4.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Perdi o vínculo com o projeto e preciso retomar', 'Modelo de mentoria confusa, o conteúdo técnico de engenharia patrimonial não foi bem sistematizado para criar uma nova cultura no aluno. Além disso, quando tratamos do acompanhamento do mentor, promessas não cumpridas, erros com relação ao meu planejamento em concreto. Infelizmente abandonei o processo por ter me decepcionado com o nível do acompanhamento. Hoje já faço minha gestão sozinho e em paralelo. Infelizmente a entrega de valor deixou de ser percebida após o fim do webnar de lançamento.', 'Melhorar em muito o modelo de mentoria e trazer mais conteúdo sistematizado para realmente educar o aluno para um novo patamar de habilidade financeira. Inclusive penso que o ganho no modelo de intermediação de vocês seria exponencial. O Adrian é realmente muito bom. Mas a empresa até aqui não conseguiu operacionalizar a entrega do valor que promete.', NULL, 'No mínimo ter uma nova possibilidade de experiência pra tornar possível mudar de opinião. Evidentemente sem custos adicionais', 'Não. Disse tudo que gostaria', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'oy10d4gmjgrhyh3aouoy10icnzukgij6', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
