INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('mn3zo1uhi3muma3tmn3zo1smo6d81uav', '2026-Q3', 'Set/2026 (T3)', '2026-09-21T18:56'::timestamptz, 'Dan Vandresen', 'dan vandresen', 'PHARUS', 'João Aliceda', 8.0, 'Neutro', 8.0, NULL, NULL, NULL, NULL, NULL, 'Em progresso, mas com dúvidas', 'Entendi o método, mas ainda não implementei o suficiente', 'Ainda estou com os investimentos acontecendo e não vi o retorno. Mas está tudo bem claro e acontecendo como previa. Tudo fluindo bem. O 10 vem a partir do memento que tiver as primerias experiencias de retorno real.', 'Contato mais próximo, consultor mais inteirado dos investimentos acontecendo, e talvez uma estrutura que trabalhe investimentos de médio prazo como o Arcadia que estou em paralelo com investimentos de curto prazo com mais giro pra conseguirmos trabalhar mais com o dinheiro. (Isso de um ponto de vista de quem não entende muito).', NULL, 'A partir do momento que eu ver os primeiros retornos acontecendo, seja do Arcadia ou da venda do apartamento comprado em leilão eu pretendo continuar com o método se os resultados forem positivos. Acredito no projeto. Vejo que o que me limita hoje é ter o capital basicamente todo alocado em investimentos de médio prazo e estar esperando pelos resultados.', 'Tem sido uma experiência positiva. No aguardo dos resultados que estamos construindo.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'mn3zo1uhi3muma3tmn3zo1smo6d81uav', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
