INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('w6xnu9441rje15u0a82ew6xnu9vnvtg1', '2026-Q3', 'Set/2026 (T3)', '2026-09-22T10:19'::timestamptz, 'Ana Paula Guillera Pereira', 'ana paula guillera pereira', 'PHARUS', 'Nelson Marques', 0.0, 'Detrator', 5.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Participei de três imersões do Adrian e fiquei encantada com seu conhecimento e a forma clara como ele ensinou. Guardei dinheiro por mais de um ano para investir na Quarta Via, com expectativa de educação continuada. Contudo, fiquei decepcionada. Os consultores patrimoniais são educados e simpáticos, mas faltam-lhes experiência e flexibilidade para lidar com imprevistos; sinto que o meu plano não foi personalizado, mas mera reprodução da metodologia das imersões com oferta de produtos (consórcios) prontos sem aprofundamento. Além disso, lembro-me de que nas imersões o Adrian informou ter um time jurídico que poderia ser consultado. Na minha primeira necessidade, esse suporte foi negado. Fazendo um paralelo com a minha profissão, se um paciente tem uma doença além do meu expertise, ajudo-o, direcionando aos especialistas corretos. Entrei com expectativa muito alta, mas não vi evolução concreta e sigo estudando por fora para realizar meus sonhos.', 'Oferecer educação continuada com temas realmente pertinentes e práticos; investir na capacitação técnica e na flexibilidade dos consultores; e aprofundar a análise sobre consórcios, indo além da simples oferta de produtos prontos para ensinar a usá-los estrategicamente nos planos.', NULL, 'Para continuar por mais 5 anos, preciso ver a Quarta Via me surpreender de verdade, oferecendo um aprofundamento estratégico tão avançado que supere o que consigo estudar sozinha. Busco mentoria de alto nível e conteúdos exclusivos que realmente impulsionem minha evolução.', 'Sim, gostaria de pontuar que minha crítica é à entidade, e não ao estrategista. A Quarta Via parece não estar preparada para o porte da responsabilidade que assumiu. Sou médica e cobro caro pelo meu atendimento, pous presto um serviço exclusivo e direto. Se delegasse a uma equipe, jamais cobraria o mesmo valor de uma consulta realizada pessoalmente por mim.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'w6xnu9441rje15u0a82ew6xnu9vnvtg1', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
