INSERT INTO nps_historico.respostas (chave_import, ciclo, ciclo_nome, data_resposta, cliente, id_cliente, programa, ep, nota_nps, categoria, nota_estrategista, nota_backoffice, nota_qv360, nota_arquitetura_patrimonial, plano_patrimonial, plano_apresentado, caminho, momento, motivo_nota, melhoria, razao_positiva, retencao_5_anos, comentario_adicional, reunioes_realizadas, inicio_programa, versao_formulario, fonte_arquivo, fonte_aba, id_resposta, ref_programa, ref_ep) VALUES ('um9md30t88b40tttc5v9eum9md3fr9pz', '2026-Q3', 'Set/2026 (T3)', '2026-09-22T10:47'::timestamptz, 'Alexandre Martini Costa', 'alexandre martini costa', 'PHARUS', 'Tales Salinas Rozo', 5.0, 'Detrator', 7.0, NULL, NULL, NULL, NULL, NULL, 'Estagnado ou travado', 'Estou travado em alguma parte e preciso de ajuda', 'Por hora não me ajudou em nada, foi feita uma análise técnica, swot, etc, mas em termos reais quando precisei rever um empréstimo mais barato, foi algo super lento, burocrático, o que eu resolvi em 15 dias com o banco demoraram 3 meses para trazer solução. E por hora não vi nenhuma solução prática que mudou ou melhorou minha vida.', 'Trazer algum resultado para prático para minha vida. Faça esse consórcio de carro, compre da sua PJ o carro da sua PF, pegue o dinheiro x e quite o banco. Entre no consórcio x com tais quotas. O leilão de imóvel y vai ter um pefil que faz sentido pra vc, sei lá. Algo que de fato sirva financeiramente pra minha vida. Por hora não estou vendo aqui como vou me aposentar em 7 anos com renda passiva.', NULL, 'ver na prática algum resultado', 'a pessoa de finanças que ficou de trazer alguma solução prática para eu pegar um empréstimo mais barato não serviu pra nada, só tomou meu tempo. Resolvi de outra forma.', NULL, NULL, 'typeform 2025-26', 'historico_typeform.csv', 'Typeform NPS', 'um9md30t88b40tttc5v9eum9md3fr9pz', 'cadastro 2026-T3 (respondente) (0 dias)', 'base mecanismos') ON CONFLICT (chave_import) DO UPDATE SET ciclo = EXCLUDED.ciclo, ciclo_nome = EXCLUDED.ciclo_nome, data_resposta = EXCLUDED.data_resposta, cliente = EXCLUDED.cliente, id_cliente = EXCLUDED.id_cliente, programa = EXCLUDED.programa, ep = EXCLUDED.ep, nota_nps = EXCLUDED.nota_nps, categoria = EXCLUDED.categoria, nota_estrategista = EXCLUDED.nota_estrategista, nota_backoffice = EXCLUDED.nota_backoffice, nota_qv360 = EXCLUDED.nota_qv360, nota_arquitetura_patrimonial = EXCLUDED.nota_arquitetura_patrimonial, plano_patrimonial = EXCLUDED.plano_patrimonial, plano_apresentado = EXCLUDED.plano_apresentado, caminho = EXCLUDED.caminho, momento = EXCLUDED.momento, motivo_nota = EXCLUDED.motivo_nota, melhoria = EXCLUDED.melhoria, razao_positiva = EXCLUDED.razao_positiva, retencao_5_anos = EXCLUDED.retencao_5_anos, comentario_adicional = EXCLUDED.comentario_adicional, reunioes_realizadas = EXCLUDED.reunioes_realizadas, inicio_programa = EXCLUDED.inicio_programa, versao_formulario = EXCLUDED.versao_formulario, fonte_arquivo = EXCLUDED.fonte_arquivo, fonte_aba = EXCLUDED.fonte_aba, id_resposta = EXCLUDED.id_resposta, ref_programa = EXCLUDED.ref_programa, ref_ep = EXCLUDED.ref_ep, imported_at = now();
